{
  "root": "main",
  "state": {
    "costBreakdown": [
      { "item": "Flights (2)", "cost": "700–1,000" },
      { "item": "Lodging (4 nights)", "cost": "700–1,000" },
      { "item": "Local transit", "cost": "80–140" },
      { "item": "Food and drinks", "cost": "520–760" },
      { "item": "Entry fees/Day trip", "cost": "180–300" },
      { "item": "Buffer", "cost": "120–200" }
    ],
    "itinerary": [
      { "day": "Day 1", "area": "Central Kyoto", "activity": "Nishiki Market", "icon": "../assets/r_004501_01_1_geo-alt.svg" },
      { "day": "Day 2", "area": "Eastern Kyoto", "activity": "Kiyomizu-dera & Gion", "icon": "../assets/r_004501_01_2_building.svg" },
      { "day": "Day 3", "area": "Arashiyama", "activity": "Tenryu-ji & River", "icon": "../assets/r_004501_01_3_tree.svg" },
      { "day": "Day 4", "area": "Nara", "activity": "Nara Park & Todai-ji", "icon": "../assets/r_004501_01_4_signpost-split.svg" },
      { "day": "Day 5", "area": "Fushimi Inari", "activity": "Departure", "icon": "../assets/r_004501_01_5_house.svg" }
    ]
  },
  "elements": {
    "main": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "md", "padding": 16 },
      "children": ["title", "costTable", "itineraryTable", "actions"]
    },
    "title": { "type": "Text", "props": { "text": "5-Day Kyoto Budget Trip Plan", "variant": "h1" }, "children": [] },
    "costTable": {
      "type": "Table",
      "props": {
        "title": "Trip Cost Snapshot (SGD)",
        "columns": [{ "key": "item", "label": "Item" }, { "key": "cost", "label": "Cost (SGD)" }],
        "statePath": "/costBreakdown",
        "domain": "generic",
        "preferredPresentation": "table"
      },
      "children": []
    },
    "itineraryTable": {
      "type": "Table",
      "props": {
        "title": "Daily Route",
        "columns": [{ "key": "day", "label": "Day" }, { "key": "area", "label": "Area" }, { "key": "activity", "label": "Activity" }],
        "statePath": "/itinerary",
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "day"
      },
      "children": []
    },
    "actions": {
      "type": "Stack",
      "props": { "direction": "horizontal", "gap": "sm" },
      "children": ["btn1", "btn2", "btn3"]
    },
    "btn1": { "type": "Button", "props": { "label": "Transit Info", "openUrl": "https://www.jr-odekake.net/english/" }, "children": [] },
    "btn2": { "type": "Button", "props": { "label": "Nara Trip", "openUrl": "https://www.jr-odekake.net/english/" }, "children": [] },
    "btn3": { "type": "Button", "props": { "label": "Kyoto Info", "openUrl": "https://kyoto.travel/en" }, "children": [] }
  }
}
